old_memo_call = '''        note = self._edit_content_note_dialog(\n            current,\n            content_type,\n        )\n'''
new_memo_call = '''        note = self._edit_content_note_dialog(\n            current,\n            content_type,\n            key,\n        )\n'''
ui = replace_once(ui, old_memo_call, new_memo_call, "memo dialog key propagation")

apply_marker = '''    def _apply_note_to_same_creator(self, source_key: str, source_note: str) -> None:\n'''
count_helper = '''    def _creator_livery_note_count(self, creator: str) -> int:\n        creator_key = (creator or "").strip().casefold()\n        if not creator_key:\n            return 0\n        return sum(\n            1\n            for record in self._custom_liveries()\n            if (record.header.creator or "").strip().casefold() == creator_key\n            and self.annotations.get(self._annotation_key(record)).note.strip()\n        )\n\n'''
ui = replace_once(ui, apply_marker, count_helper + apply_marker, "creator memo count helper")

old_apply_body = '''    def _apply_note_to_same_creator(self, source_key: str, source_note: str) -> None:\n        source_record = self._record_for_annotation_key(source_key)\n        if source_record is None:\n            return\n        creator = (source_record.header.creator or "").strip()\n        note = (source_note or "").strip()\n        if not creator:\n            QMessageBox.information(self, tr("memo.creator_missing_title"), tr("memo.creator_missing_apply"))\n            return\n        if not note:\n            QMessageBox.information(self, tr("memo.missing_title"), tr("memo.enter_first"))\n            return\n\n        # Save the source editor first, then append the same note block to every\n        # livery by the same creator. Existing target notes remain untouched in front.\n        self.annotations.set(source_key, note=note, save=False)\n        affected = 0\n        creator_key = creator.casefold()\n        for record in self._custom_liveries():\n            if (record.header.creator or "").strip().casefold() != creator_key:\n                continue\n            key = self._annotation_key(record)\n            current = self.annotations.get(key).note\n            merged = append_note(current, note)\n            if merged != current:\n                affected += 1\n            self.annotations.set(key, note=merged, save=False)\n        self.annotations.save()\n        self._refresh_annotation_widgets()\n        self._show_status(tr("memo.apply_status", creator=creator), 3500)\n        QMessageBox.information(\n            self,\n            tr("memo.apply_title"),\n            tr(\n                "memo.apply_message",\n                creator=creator,\n                targets=sum(1 for r in self._custom_liveries() if (r.header.creator or "").strip().casefold() == creator_key),\n                affected=affected,\n            ),\n        )\n\n'''
new_apply_body = '''    def _apply_note_to_same_creator(self, source_key: str, source_note: str) -> None:\n        source_record = self._record_for_annotation_key(source_key)\n        if source_record is None:\n            return\n        creator = (source_record.header.creator or "").strip()\n        note = (source_note or "").strip()\n        if not creator:\n            QMessageBox.information(self, tr("memo.creator_missing_title"), tr("memo.creator_missing_apply"))\n            return\n        if not note:\n            QMessageBox.information(self, tr("memo.missing_title"), tr("memo.enter_first"))\n            return\n\n        creator_key = creator.casefold()\n        targets = [\n            record\n            for record in self._custom_liveries()\n            if (record.header.creator or "").strip().casefold() == creator_key\n        ]\n        answer = QMessageBox.question(\n            self,\n            tr("memo.append_confirm_title"),\n            tr(\n                "memo.append_confirm_message",\n                creator=creator,\n                targets=len(targets),\n                existing=self._creator_livery_note_count(creator),\n            ),\n            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,\n            QMessageBox.StandardButton.No,\n        )\n        if answer != QMessageBox.StandardButton.Yes:\n            return\n\n        # Keep the source editor as the authoritative text for the selected item.\n        # Every other target preserves its existing memo and receives this text below it.\n        self.annotations.set(source_key, note=note, save=False)\n        affected = 0\n        for record in targets:\n            key = self._annotation_key(record)\n            current = self.annotations.get(key).note\n            merged = append_note(current, note)\n            if merged != current:\n                affected += 1\n            self.annotations.set(key, note=merged, save=False)\n        self.annotations.save()\n        self._refresh_annotation_widgets()\n        self._show_status(tr("memo.apply_status", creator=creator), 3500)\n        QMessageBox.information(\n            self,\n            tr("memo.apply_title"),\n            tr(\n                "memo.apply_message",\n                creator=creator,\n                targets=len(targets),\n                affected=affected,\n            ),\n        )\n\n'''
ui = replace_once(ui, old_apply_body, new_apply_body, "creator memo append confirmation")

UI_PATH.write_text(ui, encoding="utf-8")

